import{_ as l,a0 as o,w as r,s as g,ao as t,I as i,x as a,a1 as e,A as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const _=JSON.parse('{"title":"Linux 中的“大内存页”（hugepage）是个什么？ | LCTT x X-CMD","titleTemplate":false,"description":"Linux 中的“大内存页”（hugepage）是个什么？ | LCTT (201803) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 中的“大内存页”（hugepage）是个什么？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 中的“大内存页”（hugepage）是个什么？ | LCTT (201803) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201803/20171102 What is huge pages in Linux","title":"Linux 中的“大内存页”（hugepage）是个什么？","tag":"201803","desc":""},"relativePath":"201803/20171102 What is huge pages in Linux.md","filePath":"[post].md"}'),u={name:"201803/20171102 What is huge pages in Linux.md"};function d(h,s,c,k,m,b){const n=o("Link");return r(),g("div",null,[s[20]||(s[20]=t(`<h1 id="linux-中的-大内存页-hugepage-是个什么" tabindex="-1">Linux 中的“大内存页”（hugepage）是个什么？ <a class="header-anchor" href="#linux-中的-大内存页-hugepage-是个什么" aria-label="Permalink to “Linux 中的“大内存页”（hugepage）是个什么？”">​</a></h1><blockquote><p>学习 Linux 中的<ruby>大内存页<rt>hugepage</rt></ruby>。理解什么是“大内存页”，如何进行配置，如何查看当前状态以及如何禁用它。</p></blockquote><p><img src="https://a1.kerneltalks.com/wp-content/uploads/2017/11/hugepages-in-linux.png" alt="Huge Pages in Linux"></p><p>本文中我们会详细介绍<ruby>大内存页<rt>huge page</rt></ruby>，让你能够回答：Linux 中的“大内存页”是什么？在 RHEL6、RHEL7、Ubuntu 等 Linux 中，如何启用/禁用“大内存页”？如何查看“大内存页”的当前值？</p><p>首先让我们从“大内存页”的基础知识开始讲起。</p><h3 id="linux-中的-大内存页-是个什么玩意" tabindex="-1">Linux 中的“大内存页”是个什么玩意？ <a class="header-anchor" href="#linux-中的-大内存页-是个什么玩意" aria-label="Permalink to “Linux 中的“大内存页”是个什么玩意？”">​</a></h3><p>“大内存页”有助于 Linux 系统进行虚拟内存管理。顾名思义，除了标准的 4KB 大小的页面外，它们还能帮助管理内存中的巨大的页面。使用“大内存页”，你最大可以定义 1GB 的页面大小。</p><p>在系统启动期间，你能用“大内存页”为应用程序预留一部分内存。这部分内存，即被“大内存页”占用的这些存储器永远不会被交换出内存。它会一直保留其中，除非你修改了配置。这会极大地提高像 Oracle 数据库这样的需要海量内存的应用程序的性能。</p><h3 id="为什么使用-大内存页" tabindex="-1">为什么使用“大内存页”？ <a class="header-anchor" href="#为什么使用-大内存页" aria-label="Permalink to “为什么使用“大内存页”？”">​</a></h3><p>在虚拟内存管理中，内核维护一个将虚拟内存地址映射到物理地址的表，对于每个页面操作，内核都需要加载相关的映射。如果你的内存页很小，那么你需要加载的页就会很多，导致内核会加载更多的映射表。而这会降低性能。</p><p>使用“大内存页”，意味着所需要的页变少了。从而大大减少由内核加载的映射表的数量。这提高了内核级别的性能最终有利于应用程序的性能。</p><p>简而言之，通过启用“大内存页”，系统具只需要处理较少的页面映射表，从而减少访问/维护它们的开销！</p><h3 id="如何配置-大内存页" tabindex="-1">如何配置“大内存页”？ <a class="header-anchor" href="#如何配置-大内存页" aria-label="Permalink to “如何配置“大内存页”？”">​</a></h3><p>运行下面命令来查看当前“大内存页”的详细内容。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@kerneltalks # grep Huge /proc/meminfo</span></span>
<span class="line"><span>AnonHugePages:         0 kB</span></span>
<span class="line"><span>HugePages_Total:       0</span></span>
<span class="line"><span>HugePages_Free:        0</span></span>
<span class="line"><span>HugePages_Rsvd:        0</span></span>
<span class="line"><span>HugePages_Surp:        0</span></span>
<span class="line"><span>Hugepagesize:       2048 kB</span></span></code></pre></div><p>从上面输出可以看到，每个页的大小为 2MB（<code>Hugepagesize</code>），并且系统中目前有 <code>0</code> 个“大内存页”（<code>HugePages_Total</code>）。这里“大内存页”的大小可以从 <code>2MB</code> 增加到 <code>1GB</code>。</p><p>运行下面的脚本可以知道系统当前需要多少个巨大页。该脚本取之于 Oracle。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/bash</span></span>
<span class="line"><span>#</span></span>
<span class="line"><span># hugepages_settings.sh</span></span>
<span class="line"><span>#</span></span>
<span class="line"><span># Linux bash script to compute values for the</span></span>
<span class="line"><span># recommended HugePages/HugeTLB configuration</span></span>
<span class="line"><span>#</span></span>
<span class="line"><span># Note: This script does calculation for all shared memory</span></span>
<span class="line"><span># segments available when the script is run, no matter it</span></span>
<span class="line"><span># is an Oracle RDBMS shared memory segment or not.</span></span>
<span class="line"><span># Check for the kernel version</span></span>
<span class="line"><span>KERN=\`uname -r | awk -F. &#39;{ printf(&quot;%d.%d\\n&quot;,$1,$2); }&#39;\`</span></span>
<span class="line"><span># Find out the HugePage size</span></span>
<span class="line"><span>HPG_SZ=\`grep Hugepagesize /proc/meminfo | awk {&#39;print $2&#39;}\`</span></span>
<span class="line"><span># Start from 1 pages to be on the safe side and guarantee 1 free HugePage</span></span>
<span class="line"><span>NUM_PG=1</span></span>
<span class="line"><span># Cumulative number of pages required to handle the running shared memory segments</span></span>
<span class="line"><span>for SEG_BYTES in \`ipcs -m | awk {&#39;print $5&#39;} | grep &quot;[0-9][0-9]*&quot;\`</span></span>
<span class="line"><span>do</span></span>
<span class="line"><span>   MIN_PG=\`echo &quot;$SEG_BYTES/($HPG_SZ*1024)&quot; | bc -q\`</span></span>
<span class="line"><span>   if [ $MIN_PG -gt 0 ]; then</span></span>
<span class="line"><span>      NUM_PG=\`echo &quot;$NUM_PG+$MIN_PG+1&quot; | bc -q\`</span></span>
<span class="line"><span>   fi</span></span>
<span class="line"><span>done</span></span>
<span class="line"><span># Finish with results</span></span>
<span class="line"><span>case $KERN in</span></span>
<span class="line"><span>   &#39;2.4&#39;) HUGETLB_POOL=\`echo &quot;$NUM_PG*$HPG_SZ/1024&quot; | bc -q\`;</span></span>
<span class="line"><span>          echo &quot;Recommended setting: vm.hugetlb_pool = $HUGETLB_POOL&quot; ;;</span></span>
<span class="line"><span>   &#39;2.6&#39; | &#39;3.8&#39; | &#39;3.10&#39; | &#39;4.1&#39; ) echo &quot;Recommended setting: vm.nr_hugepages = $NUM_PG&quot; ;;</span></span>
<span class="line"><span>    *) echo &quot;Unrecognized kernel version $KERN. Exiting.&quot; ;;</span></span>
<span class="line"><span>esac</span></span>
<span class="line"><span># End</span></span></code></pre></div><p>将它以 <code>hugepages_settings.sh</code> 为名保存到 <code>/tmp</code> 中，然后运行之：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@kerneltalks # sh /tmp/hugepages_settings.sh</span></span>
<span class="line"><span>Recommended setting: vm.nr_hugepages = 124</span></span></code></pre></div><p>你的输出类似如上结果，只是数字会有一些出入。</p><p>这意味着，你系统需要 124 个每个 2MB 的“大内存页”！若你设置页面大小为 4MB，则结果就变成了 62。你明白了吧？</p><h3 id="配置内核中的-大内存页" tabindex="-1">配置内核中的“大内存页” <a class="header-anchor" href="#配置内核中的-大内存页" aria-label="Permalink to “配置内核中的“大内存页””">​</a></h3>`,23)),i("p",null,[s[1]||(s[1]=a("本文最后一部分内容是配置上面提到的 ",-1)),e(n,{href:"https://kerneltalks.com/linux/how-to-tune-kernel-parameters-in-linux/"},{default:p(()=>[...s[0]||(s[0]=[a("内核参数 ",-1)])]),_:1}),s[2]||(s[2]=a(" ，然后重新加载。将下面内容添加到 ",-1)),s[3]||(s[3]=i("code",null,"/etc/sysctl.conf",-1)),s[4]||(s[4]=a(" 中，然后输入 ",-1)),s[5]||(s[5]=i("code",null,"sysctl -p",-1)),s[6]||(s[6]=a(" 命令重新加载配置。",-1))]),s[21]||(s[21]=t(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>vm.nr_hugepages=126</span></span></code></pre></div><p>注意我们这里多加了两个额外的页，因为我们希望在实际需要的页面数量之外多一些额外的空闲页。</p><p>现在，内核已经配置好了，但是要让应用能够使用这些“大内存页”还需要提高内存的使用阀值。新的内存阀值应该为 126 个页 x 每个页 2 MB = 252 MB，也就是 258048 KB。</p><p>你需要编辑 <code>/etc/security/limits.conf</code> 中的如下配置：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>soft memlock 258048</span></span>
<span class="line"><span>hard memlock 258048</span></span></code></pre></div><p>某些情况下，这些设置是在指定应用的文件中配置的，比如 Oracle DB 就是在 <code>/etc/security/limits.d/99-grid-oracle-limits.conf</code> 中配置的。</p><p>这就完成了！你可能还需要重启应用来让应用来使用这些新的巨大页。</p><h3 id="如何禁用-大内存页" tabindex="-1">如何禁用“大内存页”？ <a class="header-anchor" href="#如何禁用-大内存页" aria-label="Permalink to “如何禁用“大内存页”？”">​</a></h3><p>“大内存页”默认是开启的。使用下面命令来查看“大内存页”的当前状态。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@kerneltalks# cat /sys/kernel/mm/transparent_hugepage/enabled</span></span>
<span class="line"><span>[always] madvise never</span></span></code></pre></div><p>输出中的 <code>[always]</code> 标志说明系统启用了“大内存页”。</p><p>若使用的是基于 RedHat 的系统，则应该要查看的文件路径为 <code>/sys/kernel/mm/redhat_transparent_hugepage/enabled</code>。</p><p>若想禁用“大内存页”，则在 <code>/etc/grub.conf</code> 中的 <code>kernel</code> 行后面加上 <code>transparent_hugepage=never</code>，然后重启系统。</p><hr>`,14)),i("p",null,[s[8]||(s[8]=a("via: ",-1)),e(n,{href:"https://kerneltalks.com/services/what-is-huge-pages-in-linux/"},{default:p(()=>[...s[7]||(s[7]=[a("https://kerneltalks.com/services/what-is-huge-pages-in-linux/",-1)])]),_:1})]),i("p",null,[s[12]||(s[12]=a("作者：",-1)),e(n,{href:"https://kerneltalks.com"},{default:p(()=>[...s[9]||(s[9]=[a("Shrikant Lavhate",-1)])]),_:1}),s[13]||(s[13]=a(" 译者：",-1)),e(n,{href:"https://github.com/lujun9972"},{default:p(()=>[...s[10]||(s[10]=[a("lujun9972",-1)])]),_:1}),s[14]||(s[14]=a(" 校对：",-1)),e(n,{href:"https://github.com/wxy"},{default:p(()=>[...s[11]||(s[11]=[a("wxy",-1)])]),_:1})]),i("p",null,[s[17]||(s[17]=a("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[15]||(s[15]=[a("LCTT",-1)])]),_:1}),s[18]||(s[18]=a(" 原创编译，",-1)),e(n,{href:"https://linux.cn/"},{default:p(()=>[...s[16]||(s[16]=[a("Linux中国",-1)])]),_:1}),s[19]||(s[19]=a(" 荣誉推出",-1))])])}const L=l(u,[["render",d]]);export{_ as __pageData,L as default};
